@page "/catalog"
@using sv_d9d87c5d08644ad9bd26f5191137b29d.Components.Catalog
@using sv_d9d87c5d08644ad9bd26f5191137b29d.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-4">Product Catalog</h3>

<div class="d-flex">
    <!-- Sidebar -->
    <div class="catalog-sidebar" style="width: 25%; min-width: 220px;">
        <CatalogFilters Categories="@_categories"
                        OnFilterApplied="HandleFilterApplied"
                        OnFilterCleared="HandleFilterCleared" />
    </div>

    <!-- Main Content -->
    <div class="catalog-main flex-grow-1 ps-4" style="width: 75%;">
        @if (_isLoading)
        {
            <div class="d-flex justify-content-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else if (_errorMessage is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error:</strong> @_errorMessage
            </div>
        }
        else if (_result is not null && _result.Items.Count == 0)
        {
            <div class="alert alert-info" role="alert">
                No products found matching your criteria.
            </div>
        }
        else if (_result is not null)
        {
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="@_result.TotalCount"
                            Page="@_result.Page"
                            PageSize="@_result.PageSize"
                            OnSortChanged="HandleSortChanged" />

            <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4 mb-4">
                @foreach (var product in _result.Items)
                {
                    <div class="col">
                        <ProductCard Product="@product"
                                     OnSelected="HandleProductSelected"
                                     OnAddToCart="HandleAddToCart" />
                    </div>
                }
            </div>

            @if (TotalPages > 1)
            {
                <CatalogPagination CurrentPage="@_currentPage"
                                   TotalPages="@TotalPages"
                                   OnPageChanged="HandlePageChanged" />
            }
        }
    </div>
</div>

@code {
    private List<string>? _categories;
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private int _pageSize = 12;
    private bool _isLoading = true;
    private string? _errorMessage;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private int TotalPages => _result is null || _result.PageSize == 0
        ? 0
        : (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        _isLoading = true;
        _errorMessage = null;

        try
        {
            if (_categories is null)
            {
                _categories = await ProductService.GetCategoriesAsync();
            }

            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, _pageSize);
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to load products: {ex.Message}";
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await LoadDataAsync();
    }

    private async Task HandleFilterCleared()
    {
        _filter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await LoadDataAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await LoadDataAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await LoadDataAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private async Task HandleAddToCart(Product product)
    {
        // Placeholder for cart functionality
        await Task.CompletedTask;
    }
}

